import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";
import { GoogleGenAI } from "@google/genai";

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // Server-side lazy-initialized Gemini generator endpoint
  app.post("/api/generate", async (req, res) => {
    try {
      const { prompt, type } = req.body;
      if (!prompt) {
        return res.status(400).json({ error: "No prompt provided" });
      }

      const apiKey = process.env.GEMINI_API_KEY;
      if (!apiKey || apiKey === "MY_GEMINI_API_KEY" || apiKey.trim() === "") {
        return res.status(200).json({
          success: false,
          warning: "Gemini API key is not configured yet. To enable live AI-Powered code generation, please configure your GEMINI_API_KEY inside the 'Settings > Secrets' panel of AI Studio.",
          code: `// Simulated high-fidelity enterprise-grade code template for:\n// "${prompt}"\n\nconst express = require('express');\nconst database = require('./db');\nconst app = express();\n\n// Middleware\napp.use(express.json());\napp.use('/auth', require('./routes/auth'));\n\n// AI-Optimized Database Sink\napp.post('/api/sink', async (req, res) => {\n  const { payload } = req.body;\n  try {\n    const response = await database.storeAndVerify(payload);\n    res.status(200).json({ status: "success", transactionId: response.id });\n  } catch (error) {\n    res.status(500).json({ error: error.message });\n  }\n});\n\napp.listen(3000, () => console.log("Service active on Port 3000"));`
        });
      }

      // Initialize GoogleGenAI SDK on demand (lazy loading)
      const ai = new GoogleGenAI({
        apiKey: apiKey,
        httpOptions: {
          headers: {
            "User-Agent": "aistudio-build",
          },
        },
      });

      const systemInstruction = 
        type === "schema"
          ? "You are an enterprise system database architect. Generate a highly professional database schema definition (e.g., PostgreSQL, Prisma, MongoDB, or SQL DDL) based on the input description. Return ONLY valid syntax or clean code comments. No markdown files or long intros."
          : "You are a senior-grade backend developer. Generate a clean, complete production-quality API route or controller file in Node.js, Express, TypeScript, Python, or Go as requested. Ensure proper error handling, logging, and security headers. Clean formatted code only.";

      const response = await ai.models.generateContent({
        model: "gemini-3.5-flash",
        contents: prompt,
        config: {
          systemInstruction,
          temperature: 0.2, // low temperature for precise code generation
        }
      });

      const generatedText = response.text || "";

      res.json({
        success: true,
        code: generatedText
      });
    } catch (error: any) {
      console.error("Gemini Generation Error:", error);
      res.status(500).json({
        success: false,
        error: error.message || "Failed to generate backend architecture"
      });
    }
  });

  // Serve static files / Vite middleware
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer().catch((err) => {
  console.error("Failed to start server", err);
});
